const CATS=[["home","집·아침"],["food","밥·카페"],["work","일·공부"],["feel","감정"],["plan","약속·계획"],["trouble","문제 생김"],["people","사람·장소"],["opic","오픽 단골"]];
const SC=(id,cat,tag,ko,en,think,x={})=>Object.assign({id,cat,tag,ko,en,think},x);
const CARDS=[
SC("h01","home",null,"집이 좀 지저분하지? 미안.","Sorry for the mess.","A mess is a messy, untidy state. When people visit and your place isn't clean, this is the natural thing to say.",{trap:"My house is a little dirty.",
  dlg:[["A","Come on in!"],["B","Thanks for having me."],["A","Sorry for the mess. I didn't have time to clean."]],
  para:"My friend came over last night. My apartment was full of boxes because I just moved. The first thing I said was, \"Sorry for the mess.\"",
  situ:"A friend visits your home, but there are clothes and dishes everywhere. What do you say when they walk in?",
  more:["Sorry for the noise. (construction at your place)","Sorry for the wait. (you were late to reply)"]}),
SC("h02","home",null,"나 방금 일어났어.","I just woke up.","just = a very short time ago. Natives use it a lot to say something happened a moment ago."),
SC("h03","home","u1","나는 보통 7시에 일어나.","I usually get up at seven.","get up = leave your bed. usually = most days. It's a routine, so simple present.",{trap:"I am usually wake up at 7."}),
SC("h04","home","u1","지금 씻는 중이야. 10분만!","I'm in the shower. Give me ten minutes!","in the shower = taking a shower right now. 'Give me + time' = please wait that long.",{alt:"I'm taking a shower right now."}),
SC("h05","home",null,"오늘 늦잠 잤어.","I overslept today.","oversleep = sleep too long by mistake. If you sleep late on purpose to relax, say 'I slept in.'",{alt:"I slept in. (on purpose)"}),
SC("h06","home","u7","폰 어디 뒀는지 모르겠네.","I don't know where I put my phone.","A question inside a sentence uses normal order: where I put, not where did I put.",{trap:"I don't know where did I put my phone."}),
SC("h07","home","u3","요즘 잠을 잘 못 자.","I haven't been sleeping well lately.","This shows a situation that started a while ago and is still going on.",{alt:"I've been having trouble sleeping."}),
SC("h08","home",null,"설거지는 내가 할게.","I'll do the dishes.","do the dishes = wash the plates, cups, and pans. 'I'll' = I decide now to do it."),
SC("h09","home","u2","이 집 산 지 5년 됐어.","I've lived here for five years.","The line starts five years ago and reaches today. I still live here.",{alt:"I've been living here for five years.",trap:"I live here for five years."}),
SC("h10","home",null,"나 그냥 집에 있을래.","I think I'll just stay in.","stay in = stay at home and not go out. 'I think I'll just…' sounds soft and relaxed.",{trap:"I will stay in my house."}),

SC("f01","food",null,"물이면 돼요.","I'm good with water.","If you're good with something, you're happy with what you have. People say it when someone offers them more.",{trap:"Water is okay to me.",
  dlg:[["A","Can I get you anything to drink?"],["B","I'm good with water, thanks."]],
  para:"At the restaurant, the server asked if I wanted juice or soda. I don't drink soda, so I said I was good with water.",
  situ:"A server asks what you'd like to drink. You only want the water already on the table. What do you say?",
  more:["I'm good, thanks. (I don't need anything.)","I'm good with anything. (Anything is fine.)"]}),
SC("f02","food",null,"배고파 죽겠어.","I'm starving.","starving = extremely hungry. People use it as a fun exaggeration.",{trap:"I'm hungry to die."}),
SC("f03","food","u6","아이스 아메리카노 한 잔 주세요.","Can I get an iced Americano, please?","'Can I get…?' is the most common way to order in a café. 'I'd like…' is a bit more formal.",{alt:"I'd like an iced Americano, please.",trap:"Give me iced Americano."}),
SC("f04","food","u4","여기 자리 있어요?","Is this seat taken?","taken = someone already has it. Use it before you sit next to a stranger.",{trap:"Is there a person here?"}),
SC("f05","food",null,"뭐 먹고 싶어?","What do you feel like eating?","feel like + -ing = want to, right now. It's softer and more casual than 'want'."),
SC("f06","food",null,"난 아무거나 좋아.","I'm good with anything.","= Anything is fine with me. You're happy with any choice.",{alt:"Anything works for me.",trap:"I like anything."}),
SC("f07","food",null,"이거 진짜 맛있다.","This is so good.","'Delicious' is correct, but 'so good' is what people really say at the table."),
SC("f08","food","u2","아침 이후로 아무것도 안 먹었어.","I haven't eaten anything since breakfast.","A gap from breakfast until now. Nothing has happened in that time."),
SC("f09","food","u8","여기 내가 진짜 좋아하는 데야.","This is a place I really love.","'a place I really love' = a name tag on 'place'. No 'that' needed.",{alt:"This is one of my favorite places."}),
SC("f10","food",null,"따로 계산할게요.","Can we pay separately?","separately = each person pays for their own food.",{alt:"Could we split the bill?"}),
SC("f11","food",null,"커피 마시면 잠이 안 와.","Coffee keeps me awake.","English often makes the thing the subject: X keeps me awake. Think: what is doing the action?",{trap:"If I drink coffee, I can't sleep.",
  dlg:[["A","Want a coffee?"],["B","No thanks. It's 9 p.m. Coffee keeps me awake."]],
  para:"I love coffee, but I never drink it after lunch. Coffee keeps me awake until 2 a.m.",
  situ:"Someone offers you coffee late in the evening. You don't want it because of your sleep. Explain why in four words.",
  more:["Exercise keeps me healthy.","This job keeps me busy."]}),
SC("f12","food",null,"저녁 먹으면서 얘기할까요?","Should we talk about it over dinner?","over = during. 'over dinner / over coffee / over lunch' means while eating or drinking.",{trap:"Can we talk about it while we are eating dinner?",
  dlg:[["A","I want to hear about your trip."],["B","Should we talk about it over dinner?"]],
  para:"My coworker and I had a lot to discuss. We were both hungry, so we talked about it over dinner.",
  situ:"You and a friend need to plan a trip, and it's almost 7 p.m. Suggest discussing it while eating.",
  more:["Let's catch up over coffee.","We talked over lunch."]}),

SC("w01","work","u1","저 마케팅 일 해요.","I work in marketing.","work in + a field = your area of work. 'work at + a company' = where you work.",{trap:"My job is marketing work."}),
SC("w02","work","u1","이번 주는 재택근무해.","I'm working from home this week.","this week + -ing = temporary. It's not your normal routine."),
SC("w03","work","u2","거기서 일한 지 3년 됐어.","I've worked there for three years.","Started three years ago, still true now.",{trap:"It's been 3 years that I work there."}),
SC("w04","work","u3","영어 공부한 지 6개월 됐어.","I've been studying English for six months.","An activity that started six months ago and is still going.",{trap:"I'm studying English for six months."}),
SC("w05","work","u4","회의가 금요일로 옮겨졌대.","The meeting got moved to Friday.","Someone moved it. 'got moved' is the casual version of 'was moved'.",{alt:"The meeting has been moved to Friday."}),
SC("w06","work",null,"마감이 내일이라 정신없어.","My deadline is tomorrow, so I'm swamped.","swamped = you have too much work to do.",{alt:"I'm super busy."}),
SC("w07","work","u7","무슨 말인지 잘 모르겠어요.","I'm not sure what you mean.","what you mean = the meaning you want to say. It's polite and soft.",{trap:"I don't understand your word."}),
SC("w08","work","u6","다시 한 번 말해 주시겠어요?","Could you say that again?","Could you…? = a polite request.",{alt:"Sorry, could you repeat that?"}),
SC("w09","work","u1","이직할까 생각 중이야.","I'm thinking about changing jobs.","I'm thinking about… = my mind is working on it, but I haven't decided.",{trap:"I think change my job."}),
SC("w10","work","u8","제가 말씀드렸던 그 프로젝트예요.","This is the project I told you about.","'the project I told you about' = the name tag tells you which project. 'about' goes to the end."),
SC("w11","work",null,"오늘은 여기까지 하죠.","Let's call it a day.","call it a day = stop working for today.",{trap:"Let's finish here today."}),
SC("w12","work",null,"요즘 젊은 사람들은 결혼을 미루고 있어.","A lot of young people are putting off getting married.","put off = do it later, not now. 'are putting off' = it's a trend these days.",{
  dlg:[["A","My cousin is 35 and still single."],["B","That's normal now. A lot of young people are putting off getting married."]],
  para:"Housing prices keep going up, and jobs are not stable. That's why a lot of young people are putting off getting married.",
  situ:"You're talking with a coworker about how people now wait longer before having a wedding. What might you say?",
  more:["I keep putting off my homework.","Don't put it off any longer."]}),

SC("e01","feel","u5","완전 심심해.","I'm so bored.","bored = how you feel. Don't say 'I'm boring' (that means you make others bored!).",{trap:"I'm so boring."}),
SC("e02","feel","u5","그 영화 진짜 지루했어.","That movie was so boring.","boring = the thing that causes the feeling."),
SC("e03","feel","u5","너무 창피했어.","I was so embarrassed.","embarrassed = you feel shy and uncomfortable because people saw something.",{trap:"I was so shame."}),
SC("e04","feel",null,"다행이다.","That's a relief.","relief = the good feeling when a worry goes away.",{alt:"Thank goodness."}),
SC("e05","feel","u3","요즘 스트레스 엄청 받고 있어.","I've been really stressed out lately.","lately + have been = something that's been going on recently.",{trap:"I receive a lot of stress."}),
SC("e06","feel",null,"기분이 좀 별로야.","I'm not in a good mood.","in a good mood = feeling happy. Simple and natural.",{alt:"I'm not feeling great."}),
SC("e07","feel","u5","그 얘기 듣고 깜짝 놀랐어.","I was really surprised to hear that.","surprised = how you felt. 'to hear that' = the reason."),
SC("e08","feel","u6","너라면 어떻게 할 거야?","What would you do if you were me?","would + if = imagining. You're asking them to imagine your situation.",{alt:"What would you do in my shoes?"}),
SC("e09","feel","u6","그러면 정말 좋겠다.","That would be great.","would = imagining it happens. Polite and warm."),
SC("e10","feel",null,"신경 쓰지 마.","Don't worry about it.","= It's not a problem. You don't need to feel bad.",{alt:"Never mind."}),
SC("e11","feel",null,"너 때문에 웃었잖아.","You made me laugh.","make + someone + verb = cause them to do it. English starts with the person who caused it.",{trap:"I laughed because of you.",
  dlg:[["A","Why are you smiling?"],["B","You made me laugh with that video."]],
  para:"I had a terrible day at work. Then my little brother did a silly dance in the kitchen. He really made me laugh.",
  situ:"Your friend tells a funny story, and you can't stop laughing. Tell them who is responsible, starting with 'You'.",
  more:["You made me cry.","That movie made me think."]}),
SC("e12","feel",null,"나 원래 걷는 거 별로 안 좋아해.","I'm not really a walker.","English often says what kind of person you are: a walker, a morning person, a coffee person.",{trap:"I don't tend to walk.",
  dlg:[["A","Let's walk there. It's only 20 minutes."],["B","Can we take a taxi? I'm not really a walker."]],
  para:"My friends love hiking, but I'm not really a walker. I'd rather sit in a café and talk.",
  situ:"Your friend wants to walk to the store, but you don't enjoy walking. Describe yourself as a type of person.",
  more:["I'm not a morning person.","I'm a coffee person."]}),

SC("p01","plan","u1","이번 주말에 뭐 해?","What are you doing this weekend?","-ing for plans. You're asking what is already planned.",{trap:"What do you do this weekend?"}),
SC("p02","plan","u1","내일 친구 만나기로 했어.","I'm meeting a friend tomorrow.","-ing = a plan that's already set.",{trap:"I decided to meet my friend tomorrow."}),
SC("p03","plan","u7","시간 되면 같이 가자.","If you're free, let's go together.","If + present = a real possibility.",{alt:"Let's go together if you have time."}),
SC("p04","plan","u6","가고 싶은데 못 갈 것 같아.","I'd love to, but I don't think I can make it.","make it = be able to come. 'I'd love to' keeps it warm."),
SC("p05","plan","u6","차라리 집에 있을래.","I'd rather stay home.","I'd rather = I prefer to."),
SC("p06","plan","u7","도착하면 연락해.","Text me when you get there.","when + present for the future. 'get there' = arrive.",{trap:"When you will arrive, contact me."}),
SC("p07","plan","u1","좀 늦을 것 같아. 미안!","I'm running a little late. Sorry!","running late = you're on your way but late. It's happening now → -ing.",{trap:"I think I will be late a little."}),
SC("p08","plan","u8","우리 처음 만났던 카페 기억나?","Do you remember the café where we first met?","where we first met = the name tag on 'the café'."),
SC("p09","plan","u6","시간 있었으면 갔을 텐데.","I would have gone if I'd had time.","would have p.p. = imagining a different past. I didn't go."),
SC("p10","plan",null,"몇 시가 괜찮아?","What time works for you?","work for you = is good or possible for you.",{trap:"What time is okay to you?"}),
SC("p11","plan","u6","잠깐 들렀다 가는 건 괜찮겠지.","I guess a quick visit wouldn't hurt.","If something wouldn't hurt, it's not a bad idea. It might even help.",{trap:"Is it okay to stay a short time?",
  dlg:[["A","Do you want to stop by your grandma's on the way?"],["B","I guess a quick visit wouldn't hurt."]],
  para:"I was tired, but my aunt lives near the station. I thought a quick visit wouldn't hurt, so I stopped by for tea.",
  situ:"You're not sure about visiting someone, but you decide a short visit is probably fine. What do you say?",
  more:["It wouldn't hurt to ask.","A little rest wouldn't hurt."]}),

SC("t01","trouble",null,"지하철에서 폰 잃어버렸어.","I lost my phone on the subway.","on the subway = inside the train."),
SC("t02","trouble","u4","내 자전거 도둑맞았어.","My bike got stolen.","The bike received the action. 'got stolen' sounds sudden and casual.",{trap:"I was stolen my bike."}),
SC("t03","trouble","u4","비행기 취소됐어.","My flight got canceled.","The flight received the action. Something happened to it."),
SC("t04","trouble","u6","아침에 차 시동이 안 걸렸어.","My car wouldn't start this morning.","wouldn't = it refused to work."),
SC("t05","trouble","u4","길 잃었어.","I got lost.","got lost = it happened to me. 'I'm lost' = I'm in that state now."),
SC("t06","trouble",null,"폰 배터리 다 됐어.","My phone died.","die = stop working because the battery is empty.",{trap:"My phone battery is finished."}),
SC("t07","trouble","u5","폰 고쳤어. (수리점에서)","I got my phone fixed.","get + thing + p.p. = someone did it for me."),
SC("t08","trouble","u3","아까부터 계속 비 와.","It's been raining for a while.","It started a while ago, and it's still going."),
SC("t09","trouble","u4","그거 어제 일어난 일이야.","That happened yesterday.","happen never takes 'was'.",{trap:"That was happened yesterday."}),
SC("t10","trouble","u5","머리 잘랐어. (미용실에서)","I got my hair cut.","Someone cut it for you.",{alt:"I got a haircut."}),

SC("r01","people","u8","캐나다 사는 친구가 있어.","I have a friend who lives in Canada.","who lives in Canada = the name tag on 'a friend'.",{trap:"I have a Canada-living friend."}),
SC("r02","people","u8","아빠가 파일럿인 친구 알지?","You know my friend whose dad is a pilot?","whose = his/her. 'whose dad' = her dad."),
SC("r03","people","u8","여기가 내가 자란 동네야.","This is the neighborhood I grew up in.","Preposition at the end: 'grew up in'."),
SC("r04","people","u1","걔 원래 조용한데 오늘 좀 이상하게 굴어.","He's usually quiet, but he's being weird today.","be being = acting that way now, not his normal self."),
SC("r05","people","u2","걔랑은 고등학교 때부터 알았어.","I've known her since high school.","know = a state, so have known + since."),
SC("r06","people","u4","우리 아파트는 10년 전에 지어졌어.","My apartment was built about ten years ago.","The apartment received the action → was built."),
SC("r07","people","u8","창이 커서 밝은 카페야.","It's a café with big windows, which makes it really bright.",", which = your comment on what you just said."),
SC("r08","people","u7","내가 제일 좋아하는 건 거기 분위기야.","What I like most is the vibe there.","What I like most = the thing that I like most. vibe = the feeling of a place.",{alt:"What I like most is the atmosphere."}),
SC("r09","people","u1","걔는 맨날 지각해. 짜증나.","He's always showing up late.","always + -ing = it happens too much, and it annoys me."),
SC("r10","people","u4","저 서울에서 태어났어요.","I was born in Seoul.","Always 'I was born'.",{trap:"I born in Seoul."}),

SC("o01","opic","u1","저는 IT 회사에 다녀요.","I work at an IT company.","work at + a company. Simple present = your normal life.",{alt:"I'm currently working at an IT company."}),
SC("o02","opic","u1","가족이랑 아파트에 살아요.","I live in an apartment with my family.","Simple present = a fact about your life."),
SC("o03","opic","u2","거기 산 지 꽤 됐어요.","I've lived there for quite a while.","for quite a while = for a fairly long time, until now."),
SC("o04","opic","u3","요즘 운동에 빠져 있어요.","I've been really into working out lately.","be into = really like. have been + lately = it's been going on recently.",{trap:"Recently I'm falling into exercise."}),
SC("o05","opic","u6","어렸을 땐 매일 밖에서 놀곤 했어요.","When I was a kid, I would play outside every day.","would + a past time = a repeated habit."),
SC("o06","opic","u6","예전엔 머리가 길었어요.","I used to have long hair.","used to = it was true in the past, not now. For states, not would."),
SC("o07","opic","u7","그래서 제가 그 공원을 좋아해요.","That's why I love that park.","That's why… = a great way to finish an answer."),
SC("o08","opic",null,"솔직히 잘 기억이 안 나요.","To be honest, I don't really remember.","To be honest = I'm telling you the truth. A natural way to buy time."),
SC("o09","opic","u8","절대 못 잊을 일이 하나 있어요.","There's one thing I'll never forget.","the name tag 'I'll never forget' describes 'one thing'.",{alt:"One thing really stands out."}),
SC("o10","opic","u6","시간이 더 있다면 여행을 더 할 거예요.","If I had more time, I would travel more.","Imagining → had + would."),
SC("o11","opic","u4","그 공연 비 때문에 취소됐어요.","The concert got canceled because of the rain.","The concert received the action → got canceled."),
SC("o12","opic","u6","질문 몇 개 드려도 될까요?","Would it be okay if I asked you a few questions?","Would it be okay if I + past = very polite. Good for OPIc role-plays.",{alt:"Can I ask you a few questions?"}),
SC("o13","opic",null,"음, 뭐라고 해야 하지…","Hmm, how should I put it…","A filler to buy time. 'put' here means say or express. Much better than silence!",{alt:"Let me think…"}),
SC("o14","opic","u7","제가 이 동네를 좋아하는 이유는 조용해서예요.","The reason I like this neighborhood is that it's quiet.","The reason (why) I… is that… = a clear way to give a reason."),
];
